<?php

declare(strict_types=1);

$value = static fn (string $key): string => is_string($_GET[$key] ?? null) ? $_GET[$key] : '';
?>
<form method="get" action="<?= $e($filterAction) ?>" class="mt-7 rounded-2xl border border-slate-200 bg-white p-5 shadow-card" aria-label="Filtros de solicitudes"><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div class="sm:col-span-2"><label for="search" class="block text-sm font-semibold">Código o asunto</label><input id="search" name="search" type="search" maxlength="100" value="<?= $e($value('search')) ?>" placeholder="Buscar solicitud" class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3 focus-visible:ring-2 focus-visible:ring-institutional-700"></div>
<?php foreach (['status' => ['Estado', 'statuses'], 'area' => ['Área', 'areas'], 'category' => ['Categoría', 'categories'], 'technician' => ['Técnico responsable', 'technicians']] as $key => [$label, $source]): ?><div><label for="<?= $key ?>" class="block text-sm font-semibold"><?= $e($label) ?></label><select id="<?= $key ?>" name="<?= $key ?>" class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3 focus-visible:ring-2 focus-visible:ring-institutional-700"><option value="">Todos</option><?php foreach ($filterOptions[$source] as $option): ?><option value="<?= (int) $option['id'] ?>" <?= $value($key) === (string) $option['id'] ? 'selected' : '' ?>><?= $e($option['name']) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
<div><label for="assignment" class="block text-sm font-semibold">Asignación</label><select id="assignment" name="assignment" class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3 focus-visible:ring-2 focus-visible:ring-institutional-700"><option value="">Todas</option><option value="unassigned" <?= $value('assignment') === 'unassigned' ? 'selected' : '' ?>>Sin asignar</option><option value="assigned" <?= $value('assignment') === 'assigned' ? 'selected' : '' ?>>Asignadas</option></select></div>
<div><label for="attention" class="block text-sm font-semibold">Atención requerida</label><select id="attention" name="attention" class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3 focus-visible:ring-2 focus-visible:ring-institutional-700"><option value="">Todas</option><option value="needed" <?= $value('attention') === 'needed' ? 'selected' : '' ?>>Por asignar o clasificar</option></select></div>
<div><label for="from" class="block text-sm font-semibold">Desde</label><input id="from" name="from" type="date" value="<?= $e($value('from')) ?>" class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3 focus-visible:ring-2 focus-visible:ring-institutional-700"></div><div><label for="to" class="block text-sm font-semibold">Hasta</label><input id="to" name="to" type="date" value="<?= $e($value('to')) ?>" class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3 focus-visible:ring-2 focus-visible:ring-institutional-700"></div></div>
<?php if ($filterErrors !== []): ?><p role="alert" class="mt-4 rounded-lg bg-rose-50 p-3 text-sm font-semibold text-rose-900"><?= $e(implode(' ', $filterErrors)) ?></p><?php endif; ?><div class="mt-5 flex flex-wrap gap-3"><button type="submit" class="min-h-11 rounded-lg bg-institutional-700 px-5 font-bold text-white hover:bg-institutional-800 focus-visible:ring-2 focus-visible:ring-institutional-700">Aplicar filtros</button><a href="<?= $e($filterAction) ?>" class="inline-flex min-h-11 items-center rounded-lg border border-slate-300 px-5 font-semibold hover:bg-slate-50">Limpiar</a></div></form>
